const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const countryName = 'Afghanistan';
  const countries = ee.FeatureCollection('FAO/GAUL/2015/boundaries');
  const afghanistan = countries.filter(ee.Filter.eq('ADM0_NAME', countryName)).first();

  if (!afghanistan) {
    console.log(`Could not find geometry for ${countryName}.`);
    console.log("C3"); // Calculation Failure due to geometry
    return;
  }

  const geometry = afghanistan.geometry();

  const startDate2017 = '2017-02-01';
  const endDate2017 = '2017-02-28';
  const startDate2018 = '2018-02-01';
  const endDate2018 = '2018-02-28';

  // 2. Data Acquisition & Check
  const collectionId = 'MODIS/006/MOD11A2'; // MODIS/Terra Land Surface Temperature/Emissivity 8-Day L3 Global 1km

  // Function to mask clouds and scale LST
  const maskAndScaleLST = (image) => {
    const lstDay = image.select('LST_Day_8d');
    const qcDay = image.select('QC_Day');

    // Bits 0-1 are LST quality. 00 = good quality, 01 = good quality (cloudy).
    // We want to exclude where quality is bad (bits 0-1 > 1) or emissivity errors (bit 2 = 1).
    // For simplicity, let's keep only 'good quality' (00).
    const qualityMask = qcDay.rightShift(0).mod(2).eq(0); // Check bit 0-1 for 00

    // Mask values outside reasonable LST range (e.g., fill values)
    const validLST = lstDay.gte(7500).and(lstDay.lte(65535)); // MODIS LST ranges: 7500 to 65535, scaled by 0.02

    return lstDay
      .updateMask(qualityMask)
      .updateMask(validLST)
      .multiply(0.02) // Scale to Kelvin
      .subtract(273.15) // Convert to Celsius
      .rename('LST_Celsius')
      .copyProperties(image, ['system:time_start']);
  };

  const col2017 = ee.ImageCollection(collectionId)
    .filterDate(startDate2017, endDate2017)
    .filterBounds(geometry)
    .map(maskAndScaleLST);

  const col2018 = ee.ImageCollection(collectionId)
    .filterDate(startDate2018, endDate2018)
    .filterBounds(geometry)
    .map(maskAndScaleLST);

  const size2017 = await col2017.size().getInfo();
  const size2018 = await col2018.size().getInfo();

  if (size2017 === 0 || size2018 === 0) {
    console.log(`2017 Images: ${size2017}, 2018 Images: ${size2018}`);
    console.log("C1"); // Empty Collection
    return;
  }

  // 3. Processing - Calculate mean LST for each period
  const reducer = ee.Reducer.mean();
  const scale = 5000; // Use a larger scale for regional average to prevent memory issues

  // Mosaic and clip to get a single image for the period, then reduce
  const meanLST2017Image = col2017.mean();
  const meanLST2018Image = col2018.mean();

  const countPixels = async (image, geom, bandName) => {
    if (!image || !bandName) return 0;
    const stats = await image.select(bandName).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geom,
      scale: scale,
      maxPixels: 1e9,
      crs: 'EPSG:4326' // Explicit CRS
    }).getInfo();
    return stats[bandName] || 0;
  };

  const count2017 = await countPixels(meanLST2017Image, geometry, 'LST_Celsius');
  const count2018 = await countPixels(meanLST2018Image, geometry, 'LST_Celsius');

  if (count2017 === 0 || count2018 === 0) {
    console.log(`2017 Images: ${size2017} (Valid Pixels: ${count2017})`);
    console.log(`2018 Images: ${size2018} (Valid Pixels: ${count2018})`);
    console.log("C2"); // No Valid Pixels after masking
    return;
  }

  // 4. Calculation
  const lst2017Result = await meanLST2017Image.reduceRegion({
    reducer: reducer,
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9,
    crs: 'EPSG:4326'
  }).get('LST_Celsius').getInfo();

  const lst2018Result = await meanLST2018Image.reduceRegion({
    reducer: reducer,
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9,
    crs: 'EPSG:4326'
  }).get('LST_Celsius').getInfo();

  // 5. Validation & Final Answer
  if (lst2017Result === null || isNaN(lst2017Result) ||
      lst2018Result === null || isNaN(lst2018Result)) {
    console.log(`2017 LST: ${lst2017Result}, 2018 LST: ${lst2018Result}`);
    console.log("C3"); // Calculation failed
    return;
  }

  console.log(`Feb 2017 Avg LST (C): ${lst2017Result.toFixed(2)} (Pixels: ${count2017})`);
  console.log(`Feb 2018 Avg LST (C): ${lst2018Result.toFixed(2)} (Pixels: ${count2018})`);

  if (lst2018Result > lst2017Result) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
